      'beginner.daily.tbl.r2.activity': 'Free gathering',
      'beginner.daily.tbl.badge.zero': 'Zero-cost',
      'beginner.daily.tbl.r3.activity': 'Fishing',
      'beginner.daily.tbl.badge.luck': 'Luck-based',
      'beginner.daily.tbl.r4.activity': 'Four-stove cooking',
